const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: '1,001 Real-World Gen AI Use Cases from Google Cloud Customers'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Right panel overlay
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.0, y: 0, w: 4.0, h: 5.625,
    fill: { color: theme.secondary, transparency: 35 }
  });

  // Accent vertical stripe
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.94, y: 0.8, w: 0.06, h: 3.2,
    fill: { color: theme.accent }
  });

  // Title
  slide.addText("1,001 Real-World\nGen AI Use Cases", {
    x: 0.5, y: 0.7, w: 5.2, h: 1.8,
    fontSize: 40, fontFace: "Georgia",
    color: "FFFFFF", bold: true, margin: 0
  });

  // Subtitle
  slide.addText("from Google Cloud Customers", {
    x: 0.5, y: 2.5, w: 5.2, h: 0.5,
    fontSize: 22, fontFace: "Calibri",
    color: theme.accent, margin: 0
  });

  // Description
  slide.addText("How leading organizations deploy generative AI across industries and agent types", {
    x: 0.5, y: 3.1, w: 5.0, h: 0.5,
    fontSize: 13, fontFace: "Calibri",
    color: theme.light, margin: 0
  });

  // Three stat badges
  const stats = [
    { num: "1,001", label: "Use Cases" },
    { num: "11", label: "Industries" },
    { num: "6", label: "Agent Types" }
  ];

  stats.forEach(function(s, i) {
    var bx = 0.5 + i * 1.7;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: bx, y: 3.9, w: 1.5, h: 0.95,
      fill: { color: theme.secondary, transparency: 45 },
      rectRadius: 0.04
    });
    slide.addText(s.num, {
      x: bx, y: 3.92, w: 1.5, h: 0.55,
      fontSize: 26, fontFace: "Georgia",
      color: theme.accent, bold: true,
      align: "center", valign: "bottom", margin: 0
    });
    slide.addText(s.label, {
      x: bx, y: 4.45, w: 1.5, h: 0.35,
      fontSize: 10, fontFace: "Calibri",
      color: theme.light, align: "center", valign: "top", margin: 0
    });
  });

  // Source line
  slide.addText("Google Cloud  |  Updated October 2025  |  10× growth from 101 original entries", {
    x: 0.5, y: 5.15, w: 5.0, h: 0.25,
    fontSize: 9, fontFace: "Calibri",
    color: theme.light, margin: 0
  });

  // Right side - 10x callout
  slide.addText("10×", {
    x: 6.2, y: 1.2, w: 3.4, h: 1.6,
    fontSize: 72, fontFace: "Georgia",
    color: theme.accent, bold: true,
    align: "center", valign: "middle", margin: 0
  });
  slide.addText("growth in 18 months", {
    x: 6.2, y: 2.8, w: 3.4, h: 0.4,
    fontSize: 16, fontFace: "Calibri",
    color: "FFFFFF", align: "center", valign: "top", margin: 0
  });

  // Right side - small context text
  slide.addText("April 2024: 101 use cases\nOctober 2025: 1,001 use cases\n400 new entries in latest update", {
    x: 6.4, y: 3.6, w: 3.0, h: 1.2,
    fontSize: 11, fontFace: "Calibri",
    color: theme.light, valign: "top", margin: 0,
    lineSpacingMultiple: 1.4
  });

  return slide;
}

if (require.main === module) {
  var pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  var theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "ffffff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide: createSlide, slideConfig: slideConfig };

