const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 3,
  title: '11 Industries × 6 Agent Types: A Taxonomy of Enterprise Gen AI'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("11 Industries × 6 Agent Types: A Taxonomy of Enterprise Gen AI", {
    x: 0.4, y: 0.25, w: 9.2, h: 0.5,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true, margin: 0, fit: "shrink"
  });

  // Subtitle
  slide.addText("A structured framework for identifying and prioritizing gen AI opportunities across the enterprise", {
    x: 0.4, y: 0.75, w: 9.2, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, margin: 0
  });

  // Build the taxonomy matrix table
  var agentTypes = ["Customer", "Employee", "Creative", "Code", "Data", "Security"];
  var industries = [
    "Automotive & Logistics",
    "Business & Prof. Services",
    "Financial Services",
    "Healthcare & Life Sciences",
    "Hospitality & Travel",
    "Manufacturing & Industrial",
    "Media, Marketing & Gaming",
    "Public Sector & Nonprofits",
    "Retail",
    "Technology",
    "Telecommunications"
  ];

  var tableRows = [];

  // Header row
  var headerRow = [{ text: "INDUSTRY", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 8, fontFace: "Calibri", align: "center", valign: "middle" } }];
  agentTypes.forEach(function(at) {
    headerRow.push({ text: at.toUpperCase(), options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 7.5, fontFace: "Calibri", align: "center", valign: "middle" } });
  });
  tableRows.push(headerRow);

  // Data rows with dot markers
  industries.forEach(function(ind, idx) {
    var rowBg = idx % 2 === 0 ? "FFFFFF" : "F0F7FC";
    var row = [{ text: ind, options: { fill: { color: rowBg }, color: theme.primary, bold: true, fontSize: 8, fontFace: "Calibri", align: "left", valign: "middle" } }];
    agentTypes.forEach(function() {
      row.push({ text: "●", options: { fill: { color: rowBg }, color: theme.accent, fontSize: 12, fontFace: "Calibri", align: "center", valign: "middle" } });
    });
    tableRows.push(row);
  });

  slide.addTable(tableRows, {
    x: 0.4, y: 1.15, w: 9.2,
    colW: [2.0, 1.2, 1.2, 1.2, 1.2, 1.2, 1.2],
    rowH: [0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28, 0.28],
    border: { pt: 0.5, color: "D0E4F0" },
    margin: [2, 4, 2, 4]
  });

  // Agent type legend row below table
  var legendY = 4.65;
  slide.addText("6 Agent Types:", {
    x: 0.4, y: legendY, w: 1.2, h: 0.25,
    fontSize: 9, fontFace: "Calibri",
    color: theme.primary, bold: true, margin: 0
  });

  var agentLabels = [
    { name: "Customer", desc: "Conversational assistants" },
    { name: "Employee", desc: "Productivity tools" },
    { name: "Creative", desc: "Content at scale" },
    { name: "Code", desc: "Developer augmentation" },
    { name: "Data", desc: "Analytics agents" },
    { name: "Security", desc: "Threat detection" }
  ];

  agentLabels.forEach(function(al, i) {
    var lx = 1.6 + i * 1.4;
    slide.addShape(pres.shapes.OVAL, {
      x: lx, y: legendY + 0.04, w: 0.14, h: 0.14,
      fill: { color: theme.accent }
    });
    slide.addText(al.name, {
      x: lx + 0.2, y: legendY, w: 1.15, h: 0.25,
      fontSize: 8, fontFace: "Calibri",
      color: theme.primary, bold: true, margin: 0
    });
  });

  // Bottom annotation
  slide.addText("Each cell represents active production deployments by leading organizations worldwide", {
    x: 0.4, y: 5.0, w: 6.0, h: 0.25,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 9.2, y: 5.15, w: 0.55, h: 0.3,
    fill: { color: theme.secondary },
    rectRadius: 0.15
  });
  slide.addText("3", {
    x: 9.2, y: 5.15, w: 0.55, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  var pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  var theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "ffffff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-03-preview.pptx" });
}

module.exports = { createSlide: createSlide, slideConfig: slideConfig };

