      x: cx, y: cardY, w: cardW, h: 0.06,
      fill: { color: card.accentColor },
      rectRadius: 0.0
    });

    // Large number
    slide.addText(card.number, {
      x: cx, y: cardY + 0.3, w: cardW, h: 1.0,
      fontSize: 42, fontFace: "Georgia",
      color: theme.primary, bold: true,
      align: "center", valign: "bottom", margin: 0
    });

    // Label
    slide.addText(card.label, {
      x: cx, y: cardY + 1.35, w: cardW, h: 0.35,
      fontSize: 12, fontFace: "Calibri",
      color: theme.accent, bold: true,
      align: "center", valign: "top", margin: 0
    });

    // Divider line
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx + 0.3, y: cardY + 1.8, w: cardW - 0.6, h: 0.015,
      fill: { color: theme.light }
    });

    // Context text
    slide.addText(card.context, {
      x: cx + 0.15, y: cardY + 1.95, w: cardW - 0.3, h: 1.2,
