    if (i < takeaways.length - 1) {
      slide.addShape(pres.shapes.RECTANGLE, {
        x: 1.05, y: iy + itemH - 0.02, w: 8.4, h: 0.01,
        fill: { color: theme.light, transparency: 40 }
      });
    }
  });

  // Bottom source
  slide.addText("Source: Google Cloud — 1,001 real-world gen AI use cases from the world's leading organizations (October 2025)", {
    x: 0.4, y: 5.05, w: 7.0, h: 0.25,
    fontSize: 8, fontFace: "Calibri",
    color: theme.secondary, margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 9.2, y: 5.15, w: 0.55, h: 0.3,
    fill: { color: theme.secondary },
    rectRadius: 0.15
  });
  slide.addText("7", {
    x: 9.2, y: 5.15, w: 0.55, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  var pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  var theme = { primary: "03045e", secondary: "0077b6", accent: "00b4d8", light: "90e0ef", bg: "ffffff" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-07-preview.pptx" });
}

module.exports = { createSlide: createSlide, slideConfig: slideConfig };

